<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/auth.php';require_once __DIR__.'/../config/helpers.php';requireRole('dosen');$base='..';$assetBase='../assets';$pageTitle='Pengajuan';require __DIR__.'/../partials/head.php'; ?><div class="dashboard-layout"><?php require __DIR__.'/../partials/sidebar.php'; ?><main class="main"><div class="mobile-head"><b>Sistem Absensi QR</b><button class="menu-toggle">☰</button></div><header class="topbar"><div><h1>Pengajuan</h1><p>Verifikasi izin dan sakit mahasiswa.</p></div><div class="top-actions"><a class="btn btn-ghost" href="../index.php">↗ Beranda</a></div></header>
<?php $did=(int)($pdo->query("SELECT d.id FROM dosen d JOIN users u ON u.username=d.nidn WHERE u.id=".userId())->fetchColumn()?:0);if($_SERVER['REQUEST_METHOD']==='POST'&&checkCsrf($_POST['csrf']??null)){$st=$pdo->prepare('UPDATE pengajuan_absensi SET status=?,catatan_dosen=?,diverifikasi_oleh=?,diverifikasi_at=NOW() WHERE id=?');$st->execute([$_POST['status'],trim($_POST['catatan']??''),$did,(int)$_POST['id']]);} $st=$pdo->prepare('SELECT p.*,m.npm,m.nama,s.tanggal,mk.nama_mk FROM pengajuan_absensi p JOIN mahasiswa m ON m.id=p.mahasiswa_id JOIN sesi_absensi s ON s.id=p.sesi_id JOIN jadwal j ON j.id=s.jadwal_id JOIN mata_kuliah mk ON mk.id=j.mata_kuliah_id WHERE j.dosen_id=? ORDER BY p.created_at DESC');$st->execute([$did]);$rows=$st->fetchAll();?><section class="section"><div class="table-wrap"><table class="table"><thead><tr><th>Mahasiswa</th><th>Sesi</th><th>Jenis</th><th>Alasan</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nama'])?><small style="display:block;color:#887d90"><?=e($r['npm'])?></small></td><td><?=e($r['tanggal'].' · '.$r['nama_mk'])?></td><td><?=e($r['jenis'])?></td><td><?=e($r['alasan'])?></td><td><span class="badge"><?=e($r['status'])?></span></td><td><?php if($r['status']==='Menunggu'):?><form method="post" style="display:flex;gap:5px"><input type="hidden" name="csrf" value="<?=e(csrfToken())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="catatan" value=""><button class="btn btn-primary" name="status" value="Disetujui">Setujui</button><button class="btn btn-danger" name="status" value="Ditolak">Tolak</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
</main></div><?php require __DIR__.'/../partials/footer.php'; ?>